import ru.alfabank.ws.eq.uwsaccountbalanceinoutparms11.UWSAccountBalanceGetOutResultSetRow;

import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;

@Mapper(componentModel = "spring")
public interface AccountBalanceGetParamsMapper {

    UWSAccountBalanceGetInParms mapToGetParams(String eanlst, String typelst);

    List<AccountBalance> mapToAccountBalanceList(List<UWSAccountBalanceGetOutResultSetRow> resultSetRow);

    @Mapping(source = "ean", target = "accountNumber")
    @Mapping(source = "type", target = "balanceType", qualifiedByName = "mapToBalanceType")
    @Mapping(source = "amount", target = "amount")
    AccountBalance mapToAccountBalance(UWSAccountBalanceGetOutResultSetRow resultRow);

    @Named("mapToBalanceType")
    default BalanceType mapToBalanceType(String code) {
        return BalanceType.getByCode(code);
    }

    default <T> String mapToUwsList(Set<T> list, int valueLength, Function<T, String> valueExtractor) {
        return list.stream()
                .filter(Objects::nonNull)
                .map(valueExtractor)
                .map(value -> StringUtils.rightPad(value, valueLength))
                .collect(Collectors.joining());
    }
}
